    // Find the element containing the list of participating nations
    const heading = Array.from(document.querySelectorAll('h2, h3')).find(el => el.textContent.includes('Participating nations'));
    if (!heading) return null;
    // Find the next sibling that contains the list
    let next = heading.nextElementSibling;
    while (next && !next.querySelector('ul, ol, table')) {
        next = next.nextElementSibling;
    }
    if (!next) return null;
    // Look for list items within
    const listItems = next.querySelectorAll('li');
    if (listItems.length) {
        const data = Array.from(listItems).map(li => li.textContent.trim()).filter(text => text.includes('('));
        return data;
    }
    // Alternatively, look for table rows
    const rows = next.querySelectorAll('tr');
    if (rows.length) {
        const data = Array.from(rows).map(row => row.textContent.trim()).filter(text => text.includes('('));
        return data;
    }
    return null;
}"}

